// Busca rows status=error_send con sdr_action!=null que necesitan retry.
// Criterio: retry_count < 3 AND (last_retry IS NULL OR last_retry < now-5min)
// Devuelve cada row como un item.
//
// NOTA: n8n vm2 sandbox no expone URLSearchParams, construimos el query string a mano.

const base = 'https://mazhrnqztnjvppgbltuq.supabase.co/rest/v1/cl001_p007_turn1_pipeline';
const select = encodeURIComponent('id,lead_email,error_send_retry_count,error_send_last_retry_at,smartlead_lead_id,smartlead_thread_id,campaign_id,hubspot_contact_id');
const qs =
  'status=eq.error_send' +
  '&sdr_action=not.is.null' +
  '&error_send_retry_count=lt.3' +
  '&select=' + select +
  '&order=sdr_action_timestamp.asc' +
  '&limit=50';
const url = base + '?' + qs;

const rows = await this.helpers.httpRequestWithAuthentication.call(
  this, 'supabaseApi',
  { method: 'GET', url, json: true }
);

const NOW = Date.now();
const MS_5MIN = 5 * 60 * 1000;
const eligible = (Array.isArray(rows) ? rows : []).filter(r => {
  if (!r.error_send_last_retry_at) return true;
  const last = Date.parse(r.error_send_last_retry_at);
  return (NOW - last) >= MS_5MIN;
});

return eligible.map(r => ({ json: r }));

// Para cada row: incrementar contador + last_retry timestamp
// y disparar webhook turn1-send-from-lovable.
// Si tras el incremento count llega a 3 (= último intento), flag para Slack.

const items = $input.all();
const out = [];
const NOW = new Date().toISOString();

for (const item of items) {
  const row = item.json;
  const pid = row.id;
  const newCount = (row.error_send_retry_count || 0) + 1;
  const isFinalAttempt = newCount >= 3;

  // PATCH row counter
  const supaUrl = 'https://mazhrnqztnjvppgbltuq.supabase.co/rest/v1/cl001_p007_turn1_pipeline?id=eq.' + pid;
  await this.helpers.httpRequestWithAuthentication.call(
    this, 'supabaseApi',
    {
      method: 'PATCH',
      url: supaUrl,
      body: { error_send_retry_count: newCount, error_send_last_retry_at: NOW },
      json: true,
      headers: { Prefer: 'return=minimal' },
    }
  );

  // Trigger the WF02 v2 send webhook. Si tiene éxito → status cambia a 'sent'
  // automáticamente, sino sigue en error_send y reintentaremos en 5 min más
  // (hasta retry_count=3).
  try {
    await this.helpers.httpRequest.call(this, {
      method: 'POST',
      url: 'https://cion8napp.nexau.es/webhook/turn1-send-from-lovable',
      body: { pipeline_id: pid },
      json: true,
      timeout: 30000,
    });
  } catch (e) {
    // Si el webhook falla, seguirá en error_send y reintenta en 5 min
  }

  out.push({ json: { ...row, new_retry_count: newCount, is_final_attempt: isFinalAttempt } });
}
return out;

// Esperar 8 segundos para dar tiempo a Smartlead/WF02 v2 a actualizar el
// status. Luego releer cada row para ver cuáles siguen en error_send
// tras intentar enviar (= retry falló).
await new Promise(r => setTimeout(r, 8000));

const items = $input.all();
const pids = items.map(i => i.json.id).map(id => '"' + id + '"').join(',');
if (!pids) return [];
const url = 'https://mazhrnqztnjvppgbltuq.supabase.co/rest/v1/cl001_p007_turn1_pipeline';
const params = new URLSearchParams({
  id: 'in.(' + pids + ')',
  select: 'id,lead_email,status,error_send_retry_count,error_send_alerted_at',
});
const rows = await this.helpers.httpRequestWithAuthentication.call(
  this, 'supabaseApi',
  { method: 'GET', url: url + '?' + params.toString(), json: true }
);

// Detectar los que siguen en error_send Y ya hicieron 3 reintentos Y
// nunca se alertó. Esos van a Slack.
const toAlert = (rows || []).filter(r =>
  r.status === 'error_send' && r.error_send_retry_count >= 3 && !r.error_send_alerted_at
);
return toAlert.map(r => ({ json: r }));

// Para cada caso final: enviar alerta Slack + marcar alerted_at
const SLACK_URL = 'https://hooks.slack.com/services/__SLACK_WEBHOOK_REDACTED__';
const items = $input.all();
const NOW = new Date().toISOString();

for (const item of items) {
  const row = item.json;
  // Slack notify
  try {
    await this.helpers.httpRequest.call(this, {
      method: 'POST',
      url: SLACK_URL,
      body: {
        text: '🚨 Auto-retry error_send agotado',
        blocks: [
          { type: 'section', text: { type: 'mrkdwn',
              text: '🚨 *3 reintentos sin éxito para enviar Turn 1*\n\n' +
                    '• Lead: `' + row.lead_email + '`\n' +
                    '• Pipeline: `' + row.id + '`\n' +
                    '• Acción: revisar manualmente en /lead/' + encodeURIComponent(row.lead_email)
          } },
        ]
      },
      json: true,
      timeout: 10000,
    });
  } catch (e) {}

  // Mark alerted to avoid re-spam
  const url = 'https://mazhrnqztnjvppgbltuq.supabase.co/rest/v1/cl001_p007_turn1_pipeline?id=eq.' + row.id;
  await this.helpers.httpRequestWithAuthentication.call(
    this, 'supabaseApi',
    {
      method: 'PATCH',
      url: url,
      body: { error_send_alerted_at: NOW },
      json: true,
      headers: { Prefer: 'return=minimal' },
    }
  );
}
return items;
